    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelItem> _channels = new();

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _twoFactorEnabled;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeConfirmation;
    private string? _sessionToRevoke;

    // Appearance state
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly Dictionary<string, (string Icon, string Label)> _sections = new()
    {
        ["profile"] = ("👤", "Profile"),
        ["notifications"] = ("🔔", "Notifications"),
        ["security"] = ("🔒", "Security"),
        ["appearance"] = ("🎨", "Appearance")
    };

    private static readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;

        var notif = notifTask.Result;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _channels = notif.MutedChannels.Select(c => new ChannelItem(c, true)).ToList();

        _securitySettings = securityTask.Result;
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = appearanceTask.Result;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    // --- Profile ---

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile Settings</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrEmpty(_avatarUrl))
                {
                    <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <p class="avatar-url-display">@_avatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control" @bind="_displayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control" @bind="_email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4" @bind="_bio"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            _displayName = _savedProfile.DisplayName;
            _email = _savedProfile.Email;
            _avatarUrl = _savedProfile.AvatarUrl;
            _bio = _savedProfile.Bio;
        }
        ShowToast("Changes discarded.", "info");
    }

    // --- Notifications ---

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notification Preferences</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-switch"></span>
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-switch"></span>
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-switch"></span>
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            @if (_channels.Any())
            {
                <div class="channel-list">
                    @foreach (var channel in _channels)
                    {
                        <label class="channel-item">
                            <input type="checkbox" checked="@channel.Muted" @onchange="(e) => channel.Muted = (bool)(e.Value ?? false)" />
                            <span>@channel.Name</span>
                        </label>
                    }
                </div>
            }
            else
            {
                <p class="text-muted">No channels available.</p>
            }

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private async Task SaveNotifications()
    {
        var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // --- Security ---

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security Settings</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▼" : "▶")</span>
                </button>

                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-row">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_twoFactorEnabled" />
                        <span class="toggle-switch"></span>
                        <span>Enable Two-Factor Authentication</span>
                    </label>
                    <span class="status-indicator @(_twoFactorEnabled ? "status-active" : "status-inactive")">
                        @(_twoFactorEnabled ? "● Enabled" : "○ Disabled")
                    </span>
                </div>
            </div>

            <div class="sessions-section">
                <h3>Active Sessions</h3>
                @if (_securitySettings?.Sessions.Any() == true)
                {
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
