    gap: 0.75rem;
    padding: 0.85rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    color: #555;
}

.settings-nav li:hover {
    background: #e9ecef;
}

.settings-nav li.active {
