namespace sv_ae94ca082bfc4214bc500f46c26c6fb3.Services;

/// <summary>
/// In-memory implementation of ISettingsService for development/demo purposes.
/// Replace with a real implementation that calls your backend API.
/// </summary>
public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new(
        "Jane Doe",
        "jane.doe@example.com",
        "https://i.pravatar.cc/150?u=jane",
        "Software developer who loves building great user experiences."
    );

    private NotificationPrefs _notificationPrefs = new(
        true, true, false,
        new List<string> { "#general", "#random", "#announcements", "#dev-talk" }
    );

    private SecuritySettings _securitySettings = new(
        true,
        DateTime.UtcNow.AddDays(-30),
        new List<ActiveSession>
        {
            new("sess-1", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
            new("sess-2", "Safari on iPhone", "New York, US", DateTime.UtcNow.AddHours(-2)),
            new("sess-3", "Firefox on Linux", "London, UK", DateTime.UtcNow.AddDays(-1))
        }
    );

    private AppearanceSettings _appearance = new("System", "Medium", "English", false);

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
        return Task.CompletedTask;
    }

    public Task<NotificationPrefs> GetNotificationPrefsAsync() => Task.FromResult(_notificationPrefs);

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        _notificationPrefs = prefs;
        return Task.CompletedTask;
    }

    public Task<SecuritySettings> GetSecuritySettingsAsync() => Task.FromResult(_securitySettings);

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        _securitySettings = _securitySettings with { LastPasswordChange = DateTime.UtcNow };
        return Task.CompletedTask;
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        var sessions = _securitySettings.Sessions.Where(s => s.Id != sessionId).ToList();
        _securitySettings = _securitySettings with { Sessions = sessions };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() => Task.FromResult(_appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        _appearance = settings;
        return Task.CompletedTask;
    }
}
