.appearance-preview {
    margin-top: 1.5rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 1.5rem;
    transition: all 0.3s;
}

.appearance-preview h4 {
    margin: 0 0 0.5rem;
